<?php require __DIR__ . '/connect.php'; require __DIR__ . '/mailer.php'; $name=trim($_POST['full_name']??''); $email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if(!$name||!$email||strlen($password)<8){header('Location: register.php?error=validation');exit;} $hash=password_hash($password,PASSWORD_DEFAULT); $token=bin2hex(random_bytes(16)); $stmt=$mysqli->prepare('INSERT INTO users(full_name,email,password_hash,activation_token) VALUES(?,?,?,?)'); $stmt->bind_param('ssss',$name,$email,$hash,$token); if(!$stmt->execute()){header('Location: register.php?error=email');exit;} $link='http://localhost/CISC3003-FinalExam-Paper02C/php/activate.php?token='.urlencode($token); send_exam_mail($email,'Activate account',$link); header('Location: login.php?registered=1'); exit; ?>
